async function countByteFrequency(file) {
  const reader = file.stream().getReader()
  const frequency = new Uint32Array(256) // 256 种字节值，内存恒定 1KB

  while (true) {
    const { done, value } = await reader.read()
    if (done) break
    // 逐块处理，不累积历史数据
    for (let i = 0; i < value.length; i++) {
      frequency[value[i]]++
    }
  }

  return frequency
}

const input = document.querySelector('input[type="file"]')
input.addEventListener("change", (e) => {
  const file = e.target.files[0] // File 继承自 Blob
  const url = URL.createObjectURL(file)

  const img = document.createElement("img")
  img.src = url
  img.onload = () => URL.revokeObjectURL(url) // 图片加载完即可释放
  document.body.appendChild(img)
})

const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: true })
const recorder = new MediaRecorder(stream, { mimeType: "video/webm" })

const chunks = []
recorder.ondataavailable = (event) => {
  if (event.data.size > 0) {
    chunks.push(event.data) // event.data 就是 Blob
  }
}

recorder.onstop = () => {
  // 将所有片段合并为一个完整的 Blob，后续可用于下载或上传
  const fullBlob = new Blob(chunks, { type: "video/webm" })
  const url = URL.createObjectURL(fullBlob)
  videoElement.src = url
}

recorder.start(1000) // 每 1000ms 触发一次 ondataavailable
setTimeout(() => recorder.stop(), 5000) // 录制 5 秒

